#!/usr/bin/env python3
"""Update HWPX playbook XML contents.

- Applies field updates from renewal_update.json
- Replaces follow-up paragraphs from followups.csv (sequence order)
- Removes hp:linesegarray from any modified paragraph to avoid stale layout cache

This script edits the extracted package under /tmp/hwpx_work/hwpx_contents.
"""

from __future__ import annotations

import copy
import csv
import json
import os
import re
import sys
import xml.etree.ElementTree as ET


HWPML_URI = "http://www.hancom.co.kr/hwpml/2010/HWPML"
HP = f"{{{HWPML_URI}}}"

APPENDIX_SENTENCE = "이 부록 문단은 그대로 유지해야 합니다."


def register_namespaces_from_root(root: ET.Element) -> None:
    # Preserve prefixes on write by registering namespaces found on the root.
    for k, v in root.attrib.items():
        if k.startswith("{http://www.w3.org/2000/xmlns/}"):
            prefix = k.split("}", 1)[1]
            ET.register_namespace(prefix, v)


def paragraph_text(p: ET.Element) -> str:
    parts = []
    for t in p.iter(HP + "t"):
        parts.append(t.text or "")
    return "".join(parts)


def set_paragraph_text(p: ET.Element, new_text: str) -> None:
    # Write new_text into the first hp:t; clear any remaining hp:t nodes.
    ts = list(p.iter(HP + "t"))
    if not ts:
        # Create minimal run/t if missing.
        run = ET.SubElement(p, HP + "run")
        t = ET.SubElement(run, HP + "t")
        t.text = new_text
        return

    ts[0].text = new_text
    for t in ts[1:]:
        t.text = ""


def remove_linesegarray(p: ET.Element) -> bool:
    removed = False
    for child in list(p):
        if child.tag == HP + "linesegarray":
            p.remove(child)
            removed = True
    return removed


def load_updates(json_path: str) -> dict:
    with open(json_path, "r", encoding="utf-8") as f:
        data = json.load(f)
    if not isinstance(data, dict):
        raise ValueError("renewal_update.json must be an object/dict")
    return data


def load_followups(csv_path: str) -> list[dict]:
    with open(csv_path, "r", encoding="utf-8") as f:
        reader = csv.DictReader(f)
        rows = list(reader)

    if not rows:
        return []

    # Identify the text column (prefer 'item', otherwise first non-sequence col)
    fieldnames = reader.fieldnames or []
    text_col = None
    if "item" in fieldnames:
        text_col = "item"
    else:
        for c in fieldnames:
            if c != "sequence":
                text_col = c
                break
    if text_col is None:
        raise ValueError("followups.csv must contain a text column (e.g. item)")

    def seq_int(r: dict) -> int:
        try:
            return int(str(r.get("sequence", "")).strip())
        except Exception as e:
            raise ValueError(f"Invalid sequence in CSV row: {r}") from e

    cleaned = []
    for r in rows:
        cleaned.append(
            {
                "sequence": seq_int(r),
                "text": (r.get(text_col) or "").strip(),
            }
        )

    cleaned.sort(key=lambda r: r["sequence"])
    return cleaned


def derive_replacements(section_roots: list[ET.Element], updates: dict) -> list[tuple[str, str]]:
    """Derive old->new replacement pairs from the existing document content."""

    def find_after_label(label: str) -> str | None:
        for root in section_roots:
            for p in root.iter(HP + "p"):
                txt = paragraph_text(p)
                if APPENDIX_SENTENCE in txt:
                    continue
                if label in txt:
                    after = txt.split(label, 1)[1]
                    return after.strip()
        return None

    # Customer and owner are on labeled lines.
    old_customer = find_after_label("고객사:")
    old_owner = find_after_label("현 담당자:")

    # Note is on a labeled line.
    old_note = find_after_label("가격 메모:")

    # Window range appears on labeled lines; capture dates.
    old_window_start = None
    old_window_end = None
    for root in section_roots:
        for p in root.iter(HP + "p"):
            txt = paragraph_text(p)
            if APPENDIX_SENTENCE in txt:
                continue
            if "갱신 윈도우" in txt:
                m = re.search(r"(\d{4}-\d{2}-\d{2})\s*~\s*(\d{4}-\d{2}-\d{2})", txt)
                if m:
                    old_window_start, old_window_end = m.group(1), m.group(2)
                    break
        if old_window_start:
            break

    # Band and escalation email are in the pricing table (section0), but as a fallback
    # we'll use the first exact-looking value we find.
    old_band = None
    old_escalation = None

    for root in section_roots:
        for tbl in root.iter(HP + "tbl"):
            for tr in tbl.findall(HP + "tr"):
                # Each tr has two tc; each tc contains subList->p
                tcs = tr.findall(HP + "tc")
                if len(tcs) < 2:
                    continue
                def tc_first_p_text(tc: ET.Element) -> str:
                    p = tc.find(f".//{HP}p")
                    return paragraph_text(p) if p is not None else ""

                left = tc_first_p_text(tcs[0]).strip()
                right = tc_first_p_text(tcs[1]).strip()
                if left == "가격 밴드" and right:
                    old_band = right
                if left == "에스컬레이션 연락처" and right:
                    old_escalation = right

    # Fallback scans (in case table parsing changes)
    if old_band is None:
        for root in section_roots:
            for p in root.iter(HP + "p"):
                txt = paragraph_text(p).strip()
                if re.fullmatch(r"[A-Za-z]+-\d+M", txt):
                    old_band = txt
                    break
            if old_band:
                break

    if old_escalation is None:
        for root in section_roots:
            for p in root.iter(HP + "p"):
                txt = paragraph_text(p).strip()
                if "@" in txt and "." in txt and " " not in txt:
                    old_escalation = txt
                    break
            if old_escalation:
                break

    # Build replacement pairs only when we have both old and new.
    pairs: list[tuple[str, str]] = []

    def add(old: str | None, new: str | None) -> None:
        if old is None or new is None:
            return
        old_s = str(old)
        new_s = str(new)
        if old_s and old_s != new_s:
            pairs.append((old_s, new_s))

    add(old_customer, updates.get("customer"))
    add(old_owner, updates.get("owner_name"))
    add(old_band, updates.get("band"))
    add(old_escalation, updates.get("escalation_email"))
    add(old_note, updates.get("note"))

    if old_window_start and old_window_end:
        new_start = updates.get("window_start")
        new_end = updates.get("window_end")
        add(old_window_start, new_start)
        add(old_window_end, new_end)
        old_range = f"{old_window_start} ~ {old_window_end}"
        new_range = f"{new_start} ~ {new_end}"
        add(old_range, new_range)

    # De-dup while preserving order
    seen = set()
    out: list[tuple[str, str]] = []
    for a, b in pairs:
        k = (a, b)
        if k in seen:
            continue
        seen.add(k)
        out.append((a, b))
    return out


def apply_replacements(root: ET.Element, replacements: list[tuple[str, str]]) -> set[int]:
    """Apply replacements across all paragraphs; return ids(modified paragraphs)."""
    modified: set[int] = set()
    if not replacements:
        return modified

    for p in root.iter(HP + "p"):
        txt = paragraph_text(p)
        if not txt:
            continue
        if APPENDIX_SENTENCE in txt:
            continue

        new_txt = txt
        for old, new in replacements:
            if old in new_txt:
                new_txt = new_txt.replace(old, new)

        if new_txt != txt:
            set_paragraph_text(p, new_txt)
            remove_linesegarray(p)
            modified.add(id(p))

    return modified


def replace_followups(section_root: ET.Element, followups: list[dict]) -> set[int]:
    """Replace the consecutive follow-up paragraphs; return ids(modified paragraphs)."""

    modified: set[int] = set()
    if not followups:
        return modified

    # section_root is expected to have paragraphs as direct children.
    children = list(section_root)

    def child_para_text(el: ET.Element) -> str:
        if el.tag != HP + "p":
            return ""
        return paragraph_text(el).strip()

    header_idx = None
    for i, el in enumerate(children):
        if el.tag == HP + "p" and child_para_text(el) == "후속 조치":
            header_idx = i
            break
    if header_idx is None:
        return modified

    # Identify the existing follow-up block after the header.
    # We consider paragraphs after header until a paragraph starting with "갱신 윈도우".
    followup_candidates: list[ET.Element] = []
    stop_idx = None
    for el in children[header_idx + 1 :]:
        if el.tag != HP + "p":
            continue
        txt = child_para_text(el)
        if txt.startswith("갱신 윈도우"):
            stop_idx = children.index(el)
            break
        followup_candidates.append(el)

    # Filter to recognizable follow-up lines.
    is_followup_line = re.compile(r"^\s*\d+\.\s*").match
    followup_paras = [p for p in followup_candidates if is_followup_line(child_para_text(p))]

    if len(followup_paras) < 3:
        # Fallback: any paragraph containing 'old follow-up'
        followup_paras = [p for p in followup_candidates if "old follow-up" in child_para_text(p)]

    if len(followup_paras) < 3:
        raise RuntimeError("Could not identify the three existing follow-up paragraphs")

    # Use exactly the first three in document order.
    followup_paras = followup_paras[:3]

    # Find insertion position (index of the first old follow-up paragraph).
    insert_at = children.index(followup_paras[0])

    # Remove the old paragraphs from their parent.
    for p in followup_paras:
        section_root.remove(p)

    # Clone formatting from the first removed paragraph.
    template = followup_paras[0]

    # Prepare id reuse/new ids.
    removed_ids = [p.attrib.get("id") for p in followup_paras]
    existing_ids = []
    for p in section_root.iter(HP + "p"):
        pid = p.attrib.get("id")
        if pid and pid.isdigit():
            existing_ids.append(int(pid))
    next_id = (max(existing_ids) + 1) if existing_ids else 1

    new_nodes: list[ET.Element] = []
    for idx, fu in enumerate(followups):
        node = copy.deepcopy(template)
        # Assign id if present
        if "id" in node.attrib:
            if idx < len(removed_ids) and removed_ids[idx] is not None:
                node.attrib["id"] = removed_ids[idx]
            else:
                node.attrib["id"] = str(next_id)
                next_id += 1

        set_paragraph_text(node, fu["text"])
        remove_linesegarray(node)
        modified.add(id(node))
        new_nodes.append(node)

    # Insert in sequence order at the old block position.
    for offset, node in enumerate(new_nodes):
        section_root.insert(insert_at + offset, node)

    return modified


def main() -> int:
    base = "/tmp/hwpx_work/hwpx_contents/Contents"
    section0_path = os.path.join(base, "section0.xml")
    section1_path = os.path.join(base, "section1.xml")

    updates = load_updates("/root/renewal_update.json")
    followups = load_followups("/root/followups.csv")

    # Parse both sections. (Follow-ups live in section1 in this template.)
    t0 = ET.parse(section0_path)
    r0 = t0.getroot()
    register_namespaces_from_root(r0)

    t1 = ET.parse(section1_path)
    r1 = t1.getroot()
    register_namespaces_from_root(r1)

    replacements = derive_replacements([r0, r1], updates)

    modified0 = apply_replacements(r0, replacements)
    modified1 = apply_replacements(r1, replacements)

    modified_followups = replace_followups(r1, followups)
    modified1 |= modified_followups

    # Ensure appendix sentence remains present (sanity check)
    appendix_ok = False
    for p in r1.iter(HP + "p"):
        if paragraph_text(p).strip() == APPENDIX_SENTENCE:
            appendix_ok = True
            break
    if not appendix_ok:
        raise RuntimeError("Appendix sentence is missing or modified")

    t0.write(section0_path, xml_declaration=True, encoding="UTF-8")
    t1.write(section1_path, xml_declaration=True, encoding="UTF-8")

    print(f"Updated section0.xml; modified paragraphs: {len(modified0)}")
    print(f"Updated section1.xml; modified paragraphs: {len(modified1)}")
    return 0


if __name__ == "__main__":
    raise SystemExit(main())

