    """Replace the consecutive follow-up paragraphs; return ids(modified paragraphs)."""

    modified: set[int] = set()
    if not followups:
        return modified

    # section_root is expected to have paragraphs as direct children.
    children = list(section_root)

    def child_para_text(el: ET.Element) -> str:
        if el.tag != HP + "p":
            return ""
        return paragraph_text(el).strip()

