            header_idx = i
            break
    if header_idx is None:
        return modified

    # Identify the existing follow-up block after the header.
    # We consider paragraphs after header until a paragraph starting with "갱신 윈도우".
    followup_candidates: list[ET.Element] = []
    stop_idx = None
    for el in children[header_idx + 1 :]:
        if el.tag != HP + "p":
            continue
        txt = child_para_text(el)
        if txt.startswith("갱신 윈도우"):
            stop_idx = children.index(el)
