    existing_ids = []
    for p in section_root.iter(HP + "p"):
        pid = p.attrib.get("id")
        if pid and pid.isdigit():
            existing_ids.append(int(pid))
    next_id = (max(existing_ids) + 1) if existing_ids else 1

    new_nodes: list[ET.Element] = []
    for idx, fu in enumerate(followups):
        node = copy.deepcopy(template)
        # Assign id if present
        if "id" in node.attrib:
            if idx < len(removed_ids) and removed_ids[idx] is not None:
                node.attrib["id"] = removed_ids[idx]
            else:
                node.attrib["id"] = str(next_id)
                next_id += 1

        set_paragraph_text(node, fu["text"])
        remove_linesegarray(node)
        modified.add(id(node))
        new_nodes.append(node)

    # Insert in sequence order at the old block position.
    for offset, node in enumerate(new_nodes):
        section_root.insert(insert_at + offset, node)

    return modified


def main() -> int:
    base = "/tmp/hwpx_work/hwpx_contents/Contents"
    section0_path = os.path.join(base, "section0.xml")
    section1_path = os.path.join(base, "section1.xml")

    updates = load_updates("/root/renewal_update.json")
    followups = load_followups("/root/followups.csv")

    # Parse both sections. (Follow-ups live in section1 in this template.)
    t0 = ET.parse(section0_path)
    r0 = t0.getroot()
    register_namespaces_from_root(r0)

    t1 = ET.parse(section1_path)
    r1 = t1.getroot()
    register_namespaces_from_root(r1)

    replacements = derive_replacements([r0, r1], updates)

    modified0 = apply_replacements(r0, replacements)
    modified1 = apply_replacements(r1, replacements)

    modified_followups = replace_followups(r1, followups)
    modified1 |= modified_followups

    # Ensure appendix sentence remains present (sanity check)
    appendix_ok = False
    for p in r1.iter(HP + "p"):
        if paragraph_text(p).strip() == APPENDIX_SENTENCE:
            appendix_ok = True
            break
    if not appendix_ok:
        raise RuntimeError("Appendix sentence is missing or modified")

    t0.write(section0_path, xml_declaration=True, encoding="UTF-8")
    t1.write(section1_path, xml_declaration=True, encoding="UTF-8")

    print(f"Updated section0.xml; modified paragraphs: {len(modified0)}")
    print(f"Updated section1.xml; modified paragraphs: {len(modified1)}")
    return 0


if __name__ == "__main__":
    raise SystemExit(main())

