def derive_replacements(section_roots: list[ET.Element], updates: dict) -> list[tuple[str, str]]:
    """Derive old->new replacement pairs based on existing document content."""

    def find_after_label(label: str) -> str | None:
        for root in section_roots:
            for p in root.iter(HP + "p"):
                txt = paragraph_text(p)
                if APPENDIX_SENTENCE in txt:
                    continue
                if label in txt:
                    return txt.split(label, 1)[1].strip()
        return None

    old_customer = find_after_label("고객사:")
    old_owner = find_after_label("현 담당자:")
    old_note = find_after_label("가격 메모:")

    old_window_start = None
    old_window_end = None
    for root in section_roots:
        for p in root.iter(HP + "p"):
            txt = paragraph_text(p)
            if APPENDIX_SENTENCE in txt:
                continue
            if "갱신 윈도우" in txt:
                m = re.search(r"(\d{4}-\d{2}-\d{2})\s*~\s*(\d{4}-\d{2}-\d{2})", txt)
                if m:
                    old_window_start, old_window_end = m.group(1), m.group(2)
                    break
        if old_window_start:
            break

    old_band = None
    old_escalation = None
    for root in section_roots:
        for tbl in root.iter(HP + "tbl"):
            for tr in tbl.findall(HP + "tr"):
                tcs = tr.findall(HP + "tc")
                if len(tcs) < 2:
                    continue

                def tc_first_p_text(tc: ET.Element) -> str:
                    p = tc.find(f".//{HP}p")
                    return paragraph_text(p) if p is not None else ""

                left = tc_first_p_text(tcs[0]).strip()
                right = tc_first_p_text(tcs[1]).strip()
                if left == "가격 밴드" and right:
                    old_band = right
                if left == "에스컬레이션 연락처" and right:
                    old_escalation = right

    pairs: list[tuple[str, str]] = []

    def add(old: str | None, new: str | None) -> None:
        if old is None or new is None:
            return
        old_s = str(old)
        new_s = str(new)
        if old_s and old_s != new_s:
            pairs.append((old_s, new_s))

    add(old_customer, updates.get("customer"))
    add(old_owner, updates.get("owner_name"))
    add(old_band, updates.get("band"))
    add(old_escalation, updates.get("escalation_email"))
    add(old_note, updates.get("note"))

    if old_window_start and old_window_end:
        new_start = updates.get("window_start")
        new_end = updates.get("window_end")
        add(old_window_start, new_start)
        add(old_window_end, new_end)
        add(f"{old_window_start} ~ {old_window_end}", f"{new_start} ~ {new_end}")

    # De-dup while preserving order.
    seen = set()
    out: list[tuple[str, str]] = []
    for a, b in pairs:
        if (a, b) in seen:
            continue
        seen.add((a, b))
        out.append((a, b))
    return out


def apply_replacements(root: ET.Element, replacements: list[tuple[str, str]]) -> int:
    """Apply replacements across all paragraphs in root.

    Returns count of modified paragraphs.
    """

    modified = 0
    for p in root.iter(HP + "p"):
        txt = paragraph_text(p)
        if not txt:
            continue
        if APPENDIX_SENTENCE in txt:
            continue

        new_txt = txt
        for old, new in replacements:
            if old in new_txt:
                new_txt = new_txt.replace(old, new)

        if new_txt != txt:
            set_paragraph_text_preserving_runs(p, new_txt)
            remove_linesegarray(p)
            modified += 1

    return modified


def replace_followups(section_root: ET.Element, followups: list[dict]) -> int:
    """Replace the three existing follow-up paragraphs with CSV items.

    Returns count of inserted follow-up paragraphs.
    """

    if not followups:
        return 0

    children = list(section_root)

    def p_text(el: ET.Element) -> str:
        if el.tag != HP + "p":
            return ""
        return paragraph_text(el).strip()

    header_idx = None
    for i, el in enumerate(children):
        if el.tag == HP + "p" and p_text(el) == "후속 조치":
            header_idx = i
            break
    if header_idx is None:
        return 0

    # Gather paragraph candidates after header until a stop marker.
    candidates: list[tuple[int, ET.Element]] = []
    for i in range(header_idx + 1, len(children)):
        el = children[i]
        if el.tag != HP + "p":
            continue
        txt = p_text(el)
        if txt.startswith("갱신 윈도우"):
            break
        candidates.append((i, el))

    is_numbered = re.compile(r"^\s*\d+\.\s*").match
    followup_paras = [el for _, el in candidates if is_numbered(p_text(el))]
    if len(followup_paras) < 3:
        followup_paras = [el for _, el in candidates if "old follow-up" in p_text(el)]

    if len(followup_paras) < 3:
        raise RuntimeError("Could not identify the three existing follow-up paragraphs")

    followup_paras = followup_paras[:3]
    insert_at = children.index(followup_paras[0])

    removed_ids = [p.attrib.get("id") for p in followup_paras]

    # Remove old follow-up paragraphs.
    for p in followup_paras:
        section_root.remove(p)

    template = followup_paras[0]

    # Determine new id values if we need to create additional paragraphs.
    existing_ids = []
    for p in section_root.iter(HP + "p"):
        pid = p.attrib.get("id")
        if pid and pid.isdigit():
            existing_ids.append(int(pid))
    next_id = (max(existing_ids) + 1) if existing_ids else 1

    inserted = 0
    for idx, fu in enumerate(followups):
        node = copy.deepcopy(template)

        if "id" in node.attrib:
            if idx < len(removed_ids) and removed_ids[idx] is not None:
                node.attrib["id"] = removed_ids[idx]
            else:
                node.attrib["id"] = str(next_id)
                next_id += 1

        set_paragraph_text_preserving_runs(node, fu["text"])
        remove_linesegarray(node)
        section_root.insert(insert_at + idx, node)
        inserted += 1

    return inserted


def ensure_mimetype_first(base_dir: str) -> None:
    """Ensure a mimetype file exists (for packaging) with common HWPX MIME."""

    mt = os.path.join(base_dir, "mimetype")
    if os.path.exists(mt):
        return
    with open(mt, "w", encoding="utf-8", newline="\n") as f:
        f.write("application/hwp+zip")


def main() -> int:
    pkg_base = "/tmp/hwpx_work/hwpx_contents"
    contents = os.path.join(pkg_base, "Contents")

    section0_path = os.path.join(contents, "section0.xml")
    section1_path = os.path.join(contents, "section1.xml")

    updates = load_updates("/root/renewal_update.json")
    followups = load_followups("/root/followups.csv")

    t0 = parse_with_registered_namespaces(section0_path)
    r0 = t0.getroot()

    t1 = parse_with_registered_namespaces(section1_path)
    r1 = t1.getroot()

    replacements = derive_replacements([r0, r1], updates)

    mod0 = apply_replacements(r0, replacements)
    mod1 = apply_replacements(r1, replacements)

    ins1 = replace_followups(r1, followups)

    # Appendix sentence must remain present and unchanged.
    appendix_ok = any(paragraph_text(p).strip() == APPENDIX_SENTENCE for p in r1.iter(HP + "p"))
    if not appendix_ok:
        raise RuntimeError("Appendix sentence is missing or modified")

    # Write back XML.
    t0.write(section0_path, xml_declaration=True, encoding="UTF-8")
    t1.write(section1_path, xml_declaration=True, encoding="UTF-8")

    ensure_mimetype_first(pkg_base)

    print(f"Updated section0.xml; modified paragraphs: {mod0}")
    print(f"Updated section1.xml; modified paragraphs: {mod1}; followups inserted: {ins1}")
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
