def parse_with_registered_namespaces(path: str) -> ET.ElementTree:
    """Parse XML and register all namespaces found in the document.

    ElementTree otherwise invents ns0/ns1 prefixes on write.
    Using iterparse(start-ns) lets us capture the original prefix mapping.
    """

    nsmap: dict[str, str] = {}
    for event, data in ET.iterparse(path, events=("start-ns",)):
        prefix, uri = data
        # Keep the first mapping we see for a given prefix.
        if prefix in nsmap:
            continue
        nsmap[prefix] = uri

    for prefix, uri in nsmap.items():
        ET.register_namespace(prefix, uri)

    # Parse again (iterparse consumed the stream).
    return ET.parse(path)


