    """Set paragraph text while preserving existing hp:t node structure.

    We replace based on the paragraph's concatenated visible text, but when
    writing back we distribute the updated string across existing hp:t nodes
    using their original lengths. This preserves run boundaries/formatting
    better than collapsing into a single run.
    """

    ts = list(p.iter(HP + "t"))
    if not ts:
        run = ET.SubElement(p, HP + "run")
        t = ET.SubElement(run, HP + "t")
        t.text = new_text
        return

    originals = [(t.text or "") for t in ts]
    lengths = [len(s) for s in originals]

    pos = 0
    for i, t in enumerate(ts):
        if i == len(ts) - 1:
